C.push({ t: "sub", x: "Il registro esteso portato a fondo scavo: dieci parti e cinquanta blocchi, ciascuno mirato a una sola questione, ciascuno chiuso con il proprio esito e con le proprie pendenze" });
C.push({ t: "gap" });
